import { Component, createEffect, Match, Show, Switch } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { WorldAnchor } from "#core/ui-next/components/world-anchor.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusContext } from "#core/ui-next/services/focus.js";

import { RaiseDiplomacyEvent } from "#base/ui/diplomacy/diplomacy-events.js";
import { CityBannerFocusContext } from "#base/ui-next/screens/city-banners/city-banner-focus.js";

import { BannerType, type CityBannerData } from "./city-banner-data.js";
import { CityBannerNameTooltip } from "./city-banner-name-tooltip.jsx";
import { CityBannerPopulation } from "./city-banner-population.jsx";
import { CityBannerProduction } from "./city-banner-production.jsx";

export interface CityBannerProps {
	/** The component ID of the city this banner represents. */
	cityID: ComponentID;
	/** Overrides the city's plot location when rendering debug banner copies. */
	location?: PlotCoord;
	/**
	 * Reactive per-city view-model store owned by `CityBanners`. Each slice is replaced by the
	 * specific engine event(s) that affect it
	 */
	data: CityBannerData;
}

const BANNER_ANCHOR_OFFSET: float3 = { x: 0, y: 0, z: 42 };

/**
 * A single world-anchored city banner
 */
const CityBannerImpl: Component<CityBannerProps> = (props) => {
	function onActivate() {
		const owner = props.cityID.owner;
		if (owner == GameContext.localPlayerID) {
			UI.Player.selectCity(props.cityID);
			return;
		}

		const otherPlayer = Players.get(owner);
		if (!otherPlayer) {
			return;
		}
		if (otherPlayer.isMajor || otherPlayer.isMinor || otherPlayer.isIndependent) {
			if (!Game.Diplomacy.hasMet(GameContext.localPlayerID, owner)) {
				return;
			}
			window.dispatchEvent(new RaiseDiplomacyEvent(owner));
		}
	}

	return (
		<WorldAnchor
			location={props.location ?? props.data.identity.location}
			offset={BANNER_ANCHOR_OFFSET}
			placement={PlacementMode.TERRAIN}
			class="city-banner -top-9 absolute flex flex-row justify-start items-center flex-nowrap bg-center whitespace-nowrap bg-no-repeat allow-pan"
			classList={{
				hidden: !props.data.status.visible,
				"city-banner--town": props.data.identity.bannerType == BannerType.Town,
				"city-banner--city":
					props.data.identity.bannerType == BannerType.City && props.data.identity.isLocalPlayerCity,
				"city-banner--city-other":
					props.data.identity.bannerType == BannerType.City && !props.data.identity.isLocalPlayerCity,
				"city-banner--citystate": props.data.identity.bannerType == BannerType.CityState,
				"city-banner--village": props.data.identity.bannerType == BannerType.Village,
				"city-banner--has-religion": props.data.religion.hasReligion,
				"city-banner--conquered": props.data.conquered,
				"city-banner--unrest": props.data.status.hasUnrest,
				"city-banner--razing": props.data.status.isBeingRazed,
				"city-banner--friendly": props.data.relationship == "friendly",
				"city-banner--hostile": props.data.relationship == "hostile",
				"city-banner--neutral": props.data.relationship == "neutral",
			}}
			style={{
				"--player-color-primary": props.data.identity.playerColorPrimary,
				"--player-color-secondary": props.data.identity.playerColorSecondary,
			}}
		>
			<FocusContext.Provider value={CityBannerFocusContext}>
				<Activatable
					disableFocus
					name="CityBanner"
					onActivate={onActivate}
					class="flex flex-row justify-start items-center flex-nowrap"
					style={{ "pointer-events": "none" }}
					disabled={props.data.status.disabled()}
				>
					<div class="city-banner__container flex flex-col mt-2 pointer-events-none">
						<div class="city-banner__stretch absolute flex flex-row justify-center align-center w-full h-8 top-1\.5 pointer-events-none">
							<div class="city-banner__city-state-border absolute -left-2 -right-2 -top-0 -bottom-0" />
							<div class="city-banner__city-state-ring absolute -left-1 -right-1 top-1 bottom-0" />
							<Show
								when={props.data.identity.bannerType == BannerType.Town}
								fallback={
									<CityBannerNameTooltip data={props.data.identity}>
										<div class="city-banner__stretch-bg absolute inset-0 pointer-events-none" />
									</CityBannerNameTooltip>
								}
							>
								<Tooltip.Text text="LOC_CAPITAL_SELECT_PROMOTION_NONE">
									<div class="city-banner__stretch-bg absolute inset-0 pointer-events-none" />
								</Tooltip.Text>
							</Show>
						</div>
						<div class="city-banner__name-container relative flex justify-between">
							<CityBannerNameTooltip data={props.data.identity}>
								<div class="city-banner__portrait relative pointer-events-auto flex">
									<div class="city-banner__portrait-bg1 absolute inset-0 bg-center bg-cover bg-no-repeat" />
									<div class="city-banner__portrait-bg2 absolute inset-x-0 top-0 -bottom-2 bg-center bg-cover bg-no-repeat" />
									<div
										class="city-banner__portrait-img absolute -left-2 -right-2 -top-1 bottom-0 bg-cover bg-center bg-no-repeat pointer-events-none"
										style={{ "background-image": `url('${props.data.identity.portraitIcon}')` }}
									/>
								</div>
							</CityBannerNameTooltip>
							<div class="pointer-events-auto cursor-pointer max-h-10 relative flex flex-col">
								<div class="flex flex-row">
									<Switch>
										<Match when={props.data.capital.isOriginalCapitalCurrent}>
											<Tooltip.Text text="LOC_UI_CITY_CAPITAL_OG_CURR_DESC">
												<div class="city-banner__original-capital-curr-star w-6 h-6 bg-cover bg-no-repeat pointer-events-auto" />
											</Tooltip.Text>
										</Match>
										<Match when={props.data.capital.isCapital}>
											<Tooltip.Text text="LOC_UI_CITY_CAPITAL_CURR_DESC">
												<div class="city-banner__capital-star w-6 h-6 bg-cover bg-no-repeat pointer-events-auto" />
											</Tooltip.Text>
										</Match>
										<Match when={props.data.capital.isOriginalCapital}>
											<Tooltip.Text text="LOC_UI_CITY_CAPITAL_OG_DESC">
												<div class="city-banner__original-capital-star w-6 h-6 bg-cover bg-no-repeat pointer-events-auto city-banner__town-original-capital-star" />
											</Tooltip.Text>
										</Match>
									</Switch>
									<Show
										when={props.data.identity.bannerType == BannerType.Town}
										fallback={
											<CityBannerNameTooltip data={props.data.identity}>
												<p class="city-banner__name font-title text-base uppercase">
													<L10n.Compose text={props.data.identity.name} />
												</p>
											</CityBannerNameTooltip>
										}
									>
										<Tooltip.Text text="LOC_CAPITAL_SELECT_PROMOTION_NONE">
											<p class="city-banner__name font-title text-base uppercase">
												<L10n.Compose text={props.data.identity.name} />
											</p>
										</Tooltip.Text>
									</Show>
								</div>
								<div class="city-banner__status-religion relative flex flex-row">
									<Tooltip.Text text={props.data.status.statusTooltip}>
										<div class="city-banner__status flex justify-center align-center opacity-100 pointer-events-auto">
											<div class="city-banner__status-background h-full w-full absolute" />
											<div
												class="city-banner__status-icon absolute w-full h-full bg-no-repeat"
												style={{ "background-image": props.data.status.statusIcon }}
											/>
										</div>
									</Tooltip.Text>
									<Show when={props.data.religion.hasReligion}>
										<div class="city-banner__religion self-center relative flex flex-row">
											<Tooltip.Text
												text={props.data.religion.urbanReligionTooltip}
												args={props.data.religion.urbanReligionTooltipArgs}
											>
												<div class="city-banner__religion-symbol-bg pointer-events-auto">
													<Icon
														isUrl
														name={props.data.religion.urbanReligionIcon}
														class="city-banner__religion-symbol"
													/>
												</div>
											</Tooltip.Text>
											<Show when={props.data.religion.showRuralReligion}>
												<Tooltip.Text
													text={props.data.religion.ruralReligionTooltip}
													args={props.data.religion.ruralReligionTooltipArgs}
												>
													<div class="city-banner__religion-symbol-bg pointer-events-auto religion-bg--right">
														<Icon
															isUrl
															name={props.data.religion.ruralReligionIcon}
															class="city-banner__religion-symbol religion-symbol--right"
														/>
													</div>
												</Tooltip.Text>
											</Show>
										</div>
									</Show>
									<Show when={!props.data.status.tradeNetworkHidden}>
										<Tooltip.Text text={props.data.status.tradeNetworkTooltip}>
											<div class="city-banner__trade-network flex justify-center align-center pointer-events-auto">
												<div class="city-banner__trade-network-background h-full w-full absolute" />
												<div class="city-banner__trade-network-icon absolute w-full h-full bg-no-repeat" />
											</div>
										</Tooltip.Text>
									</Show>
								</div>
							</div>
							<div class="city-banner__population-container city-banner__queue-container queue-growth items-center justify-center w-8 h-6 -mt-2">
								<div class="city-banner__population">
									<CityBannerPopulation
										cityID={props.cityID}
										population={props.data.status.population}
										currentFood={props.data.status.currentFood}
										canGrow={props.data.status.canGrow}
										foodPerTurn={props.data.status.foodPerTurn}
									/>
								</div>
							</div>
							<Show when={props.data.status.showProductionQueue}>
								<div class="city-banner__production-container city-banner__queue-container queue-production items-center justify-center w-8 h-6 -mt-2">
									<div class="city-banner__production">
										<CityBannerProduction
											currentProduction={props.data.status.currentProduction}
											buildQueue={props.data.status.buildQueue}
											turnsLeft={props.data.status.turnsLeft}
											percent={props.data.status.percent}
										/>
									</div>
								</div>
							</Show>
							<Show
								when={
									props.data.identity.bannerType == BannerType.CityState ||
									props.data.identity.bannerType == BannerType.Village
								}
							>
								<div class="city-banner__city-state-container justify-center">
									<div class="city-banner__city-state-type size-7 self-center align-center justify-center flex">
										<Tooltip.Text text={props.data.identity.cityStateTypeName}>
											<div
												class="city-banner__city-state-icon size-8 self-center align-center bg-cover bg-no-repeat"
												style={{ "background-image": props.data.identity.cityStateIcon }}
												ref={(el) => {
													createEffect(() => {
														el.style.setProperty(
															"fxs-background-image-tint",
															props.data.identity.cityStateColor,
														);
													});
												}}
											/>
										</Tooltip.Text>
									</div>
								</div>
							</Show>
						</div>
					</div>
					<div class="items-center -ml-12 mt-10 city-banner__right-container flex flex-row">
						<Show when={props.data.conquered}>
							<Tooltip.Text text="LOC_CITY_BANNER_CONQUERED_TOOLTIP">
								<div class="flex-auto -mr-3 flex flex-col">
									<div class="city-banner__conquered-icon relative size-14 -mr-6 bg-cover bg-no-repeat flex" />
								</div>
							</Tooltip.Text>
						</Show>
						<Show when={props.data.status.hasUnrest}>
							<div class="city-banner__unrest -mr-3 flex flex-col">
								<div class="city-banner__unrest-icon relative size-14 bg-cover bg-no-repeat flex" />
								<div class="city-banner__time-container -mt-3 pr-2 flex flex-row">
									<div class="city-banner__time-icon self-center bg-cover bg-no-repeat size-6 ml-1" />
									<div class="city-banner__time-text self-center font-body-xs text-white">
										{props.data.status.unrestTurns}
									</div>
								</div>
							</div>
						</Show>
						<Show when={props.data.status.isBeingRazed}>
							<div class="city-banner__razing -mr-3 flex flex-col">
								<div class="city-banner__razing-icon relative size-14 bg-cover bg-no-repeat flex" />
								<div class="city-banner__time-container -mt-3 pr-2 flex flex-row">
									<div class="city-banner__time-icon self-center bg-cover bg-no-repeat size-6 ml-1" />
									<div class="city-banner__time-text self-center font-body-xs text-white">
										{props.data.status.razedTurns}
									</div>
								</div>
							</div>
						</Show>
					</div>
				</Activatable>
			</FocusContext.Provider>
		</WorldAnchor>
	);
};

export const CityBanner = ComponentRegistry.register("CityBanner", CityBannerImpl);
